from pathlib import Path
import re, html, shutil
ROOT=Path(__file__).resolve().parent
D=ROOT/'dist'
D.mkdir(exist_ok=True)
# A GitHub checkout keeps published static assets at the repository root.
if (ROOT/'assets').is_dir():
 shutil.copytree(ROOT/'assets', D/'assets', dirs_exist_ok=True)
for static_file in ['robots.txt','sitemap.xml','.nojekyll']:
 if (ROOT/static_file).is_file(): shutil.copyfile(ROOT/static_file,D/static_file)
REF=ROOT/'source-reference'
ORIGIN='https://ghostak108.github.io'
REMOTE='assets/img/'
ARROW='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>'
PLAY='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m9 5 11 7-11 7z"/></svg>'
MARK='<span class="brand-mark" aria-hidden="true"><i></i><i></i></span>'
VIDEO_IDS=list(dict.fromkeys(re.findall(r'i.ytimg.com/vi/([^/]+)/', (REF/'index.html').read_text())))
SOCIALS=[('Instagram','https://www.instagram.com/zweiklang_music/'),('YouTube','https://www.youtube.com/@zweiklang_music'),('SoundCloud','https://soundcloud.com/zweiklang_music'),('Facebook','https://www.facebook.com/profile.php?id=61571572757775'),('WhatsApp','https://wa.me/4915679748536')]
def socials():return ''.join(f'<a href="{u}" target="_blank" rel="noopener noreferrer">{n}{ARROW}</a>' for n,u in SOCIALS)
def header(page):
 def url(id):return '#'+id if page=='index' else 'index.html#'+id
 links=''.join(f'<a href="{url(id)}" data-section="{id}">{name}</a>' for id,name in [('music','Musik'),('watch','Sessions'),('about','Das Duo'),('events','Live')])
 return f'''<a class="skip-link" href="#main">Zum Inhalt</a><header class="site-header"><div class="header-inner"><a class="brand" href="index.html" aria-label="ZweiKlang – Startseite">{MARK}<span>ZweiKlang<span class="brand-period">.</span></span></a><nav class="desktop-nav" aria-label="Hauptnavigation">{links}</nav><div class="header-actions"><a class="button button-small" href="{url('contact')}">Booking {ARROW}</a><button class="menu-toggle" aria-expanded="false" aria-controls="mobileNav" aria-label="Menü öffnen"><span></span><span></span></button></div></div><div class="reading-progress" aria-hidden="true"></div></header><dialog id="mobileNav" class="mobile-menu" aria-label="Navigation"><div class="menu-top"><span class="eyebrow">ZweiKlang · Freiburg</span><button class="menu-close" aria-label="Menü schließen">×</button></div><nav aria-label="Mobile Navigation">{links}<a href="{url('contact')}">Booking {ARROW}</a></nav><div class="menu-bottom">House music. Good company.<a href="mailto:zweiklangkontakt@gmail.com">zweiklangkontakt@gmail.com</a></div></dialog>'''
def footer():return f'''<footer class="site-footer"><div class="container"><div class="footer-top"><div><a class="brand" href="index.html">{MARK}<span>ZweiKlang.</span></a><p>Aus Freiburg. Für den Moment.</p></div><div class="footer-nav"><a href="about.html">Das Duo</a><a href="videos.html">Alle Sessions</a><a href="events.html">Live &amp; Archiv</a><a href="contact.html">Kontakt</a></div><div class="footer-socials">{socials()}</div></div><div class="footer-wordmark" aria-hidden="true">ZweiKlang<span>®</span></div><div class="footer-bottom"><span>© <span data-year>2026</span> ZweiKlang</span><div><a href="contact.html#legal">Impressum</a><a href="contact.html#privacy">Datenschutz</a><button class="motion-toggle" type="button" aria-pressed="false" hidden>Animationen pausieren</button></div><a href="#main">Nach oben ↑</a></div></div></footer>'''.replace('<span>®</span>','<span>↗</span>')
def page(name,title,description,body):
 canonical=ORIGIN+('/' if name=='index' else '/'+name+'.html')
 (D/(name+'.html')).write_text(f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="theme-color" content="#f5f2e9"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/logo.png"><link rel="icon" href="assets/logo.png"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body data-page="{name}">{header(name)}<noscript><nav class="noscript-nav" aria-label="Navigation ohne JavaScript"><a href="index.html#music">Musik</a><a href="videos.html">Sessions</a><a href="about.html">Das Duo</a><a href="contact.html">Kontakt</a></nav></noscript><main id="main">{body}</main>{footer()}</body></html>''')
def section_head(number,eyebrow,title,aside=''):
 return f'<div class="section-heading reveal"><div><p class="eyebrow"><span>{number} /</span> {eyebrow}</p><h2>{title}</h2></div>{aside}</div>'
def video_cards(ids):
 return ''.join(f'''<article class="session-card reveal" data-search="DJ Set {VIDEO_IDS.index(id)}"><a href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener noreferrer" aria-label="DJ Set #{VIDEO_IDS.index(id):02d} auf YouTube ansehen"><div class="session-image"><img src="https://i.ytimg.com/vi/{id}/hqdefault.jpg" alt="Vorschaubild von ZweiKlang DJ Set {VIDEO_IDS.index(id)}" loading="lazy" width="480" height="270"><span class="session-number">SESSION / {VIDEO_IDS.index(id):02d}</span><span class="play-orb">{PLAY}</span><span class="image-fallback" aria-hidden="true">ZweiKlang.<br>LIVE SESSION</span></div><div class="session-caption"><div><h3>DJ Set #{VIDEO_IDS.index(id):02d}</h3><p>ZweiKlang · Live Session</p></div><span class="round-arrow">{ARROW}</span></div></a></article>''' for id in ids)
def booking_form():return f'''<form class="booking-form" action="mailto:zweiklangkontakt@gmail.com" method="get"><div class="form-heading"><span class="eyebrow">Dein nächster guter Abend</span><h3>Erzähl uns von deiner Idee.</h3></div><div class="form-grid"><label>Dein Name <span aria-hidden="true">*</span><input name="name" autocomplete="name" required maxlength="100" placeholder="Wie heißt du?"></label><label>E-Mail <span aria-hidden="true">*</span><input name="email" type="email" autocomplete="email" required maxlength="200" placeholder="du@beispiel.de"></label><label>Was planst du?<select name="format"><option>Live DJ Set</option><option>YouTube-Kooperation</option><option>All Night Long</option><option>Collab / Remix</option><option>Presse / Media</option><option>Etwas anderes</option></select></label><label>Wunschdatum (optional)<input name="date" type="date"></label></div><label>Location / Ort (optional)<input name="venue" maxlength="200" placeholder="Club, Café, Rooftop …"></label><label>Deine Nachricht <span aria-hidden="true">*</span><textarea name="message" required maxlength="3000" rows="4" placeholder="Was plant ihr? Schreibt uns gern, wann, wo und wie lange wir spielen sollen."></textarea></label><p class="form-note">* Pflichtfelder · Empfänger: zweiklangkontakt@gmail.com. Wähle deine E-Mail-App oder Gmail. Dort kannst du die Anfrage prüfen und abschicken.</p><button class="button" type="submit">E-Mail-App öffnen {ARROW}</button><button class="text-button gmail-request" type="button">In Gmail öffnen ↗</button><p class="form-status" role="status" aria-live="polite"></p><details class="email-fallback"><summary>Kein E-Mail-Programm eingerichtet?</summary><p>Schreibe direkt an <a href="mailto:zweiklangkontakt@gmail.com">zweiklangkontakt@gmail.com</a> oder kopiere deine Anfrage.</p><button class="text-button copy-request" type="button">Anfrage kopieren ↗</button><textarea class="copy-output" aria-label="Anfrage zum manuellen Kopieren" readonly hidden></textarea></details></form>'''
MUSIC=f'''<section id="music" class="section music-section"><div class="container">{section_head('01','Musik','Einfach mal<br><em>treiben lassen.</em>','<p>Ein Set vom Opfinger Baggersee.<br>Organischer Groove, tiefe Bässe und Zeit zum Abschalten.</p>')}<div class="listening-room reveal"><div class="record-art" aria-hidden="true"><span class="art-label">ZK / FREIBURG SESSIONS</span><div class="record"><div class="record-label">Zwei<br>Klang<span>SIDE A · HOUSE MUSIC</span></div></div><span class="art-bottom">GOOD MUSIC. GOOD COMPANY.</span></div><div class="listening-content"><p class="eyebrow"><span class="status-dot"></span> The lakeside session</p><h3>Opfinger<br>Baggersee.</h3><p>Ein Stück Sommer zum Mitnehmen. Unser DJ-Set direkt auf SoundCloud.</p><div class="player-area"><button class="button load-player" type="button">{PLAY} Set anhören</button><p class="player-note">Lädt den SoundCloud-Player. Dabei werden Daten an SoundCloud übertragen.</p><div class="player-host" hidden></div><p class="player-status" role="status" aria-live="polite"></p></div><div class="inline-links"><a href="https://soundcloud.com/zweiklang_music" target="_blank" rel="noopener noreferrer">Auf SoundCloud hören {ARROW}</a><a href="https://soundcloud.com/kellisae/right-now-atjazz-vocal-mix-1?in=zweiklang_music/sets/zweiklang-weihnachts-session" target="_blank" rel="noopener noreferrer">Tracklist {ARROW}</a></div></div></div></div></section>'''
ABOUT=f'''<section id="about" class="section about-section"><div class="container about-layout"><div class="duo-pictures reveal"><figure class="portrait portrait-ghostak"><img src="assets/ghostak-sunset.jpg" alt="ghostak ohne Kopfhörer am DJ-Pult bei Sonnenuntergang" loading="lazy" width="1365" height="2048"><figcaption><span>01 /</span> ghostak</figcaption></figure><figure class="portrait portrait-artemis"><img src="assets/artemis-sunset.jpg" alt="artemis mit Kopfhörern am DJ-Pult bei Sonnenuntergang" loading="lazy" width="1365" height="2048"><figcaption><span>02 /</span> artemis</figcaption></figure><div class="duo-stamp" aria-hidden="true">TWO MINDS<br>ONE GROOVE ↗</div></div><div class="about-copy reveal"><p class="eyebrow"><span>03 /</span> Das Duo</p><h2>Zwei Freunde.<br>Eine <em>Frequenz.</em></h2><p class="lead">Wir sind ghostak &amp; artemis aus Freiburg. Was uns verbindet? Die Begeisterung für House.</p><p>Irgendwann wurde aus gemeinsam Musik hören gemeinsam auflegen. Heute spielen wir in Bars und Clubs und nehmen seit 2025 auch YouTube-Sets auf – mit besonderen Locations und Drohnen-Shots von Artemis.</p><blockquote>„Wir passen uns der aktuellen Situation an und begeistern so die Crowd.“</blockquote><a class="text-link" href="about.html">Mehr über ZweiKlang {ARROW}</a></div></div></section>'''
EVENT_ROWS='''<div class="event-row"><time datetime="2025-10-21"><strong>21</strong><span>OKT · 2025</span></time><div><h3>Fili Café</h3><p>Freiburg · All Night Long mit Sven K.</p></div><span class="event-time">21:00–02:30</span><span class="event-tag">Club night</span></div><div class="event-row"><time datetime="2025-03-29"><strong>29</strong><span>MÄR · 2025</span></time><div><h3>Mondhalde</h3><p>Freiburg · Jazz House &amp; FPV-Drohne</p></div><span class="event-time">16:00–18:00</span><span class="event-tag">Outdoor session</span></div><div class="event-row"><time datetime="2025-03-08"><strong>08</strong><span>MÄR · 2025</span></time><div><h3>Rooftop Sunset</h3><p>Freiburg-Betzenhausen · Organic House · Private Party</p></div><span class="event-time">17:00–19:00</span><span class="event-tag">Rooftop session</span></div>'''
EVENTS=f'''<section id="events" class="section events-section"><div class="container">{section_head('04','Live & Erinnerungen','Gute Orte.<br><em>Noch bessere Nächte.</em>','<div><p>Ein Blick zurück auf unsere Sessions.<br>Neue Termine? Schreib uns.</p><a class="text-link" href="#contact">Termin anfragen '+ARROW+'</a></div>')}<p class="archive-label">Rückblick / 2025</p><div class="event-list reveal">{EVENT_ROWS}</div><a class="text-link archive-link" href="events.html">Zum Eventarchiv {ARROW}</a></div></section>'''
SERVICES=f'''<section id="services" class="section services-section"><div class="container">{section_head('05','Booking','Euer Ort.<br><em>Unser Sound.</em>','<p>Jeder Gig beginnt bei euch: mit der Location, der Stimmung und dem Moment. Format, Dauer und Preis stimmen wir gemeinsam ab.</p>')}<div class="service-grid"><article class="service-card reveal"><span class="service-index">01 / LIVE</span><h3>Ein Abend,<br>der bleibt.</h3><p>Live DJ Set für Bar, Café oder Club. Von entspanntem Ambiente bis zur Main Time.</p><ul><li>2–3 Stunden</li><li>Controller &amp; Anfahrt inklusive</li><li>2 Stunden ab 150 €*</li></ul><a href="#contact" class="text-link" data-booking="Live DJ Set">Live-Set anfragen {ARROW}</a></article><article class="service-card reveal"><span class="service-index">02 / FILM</span><h3>Eure Location.<br>Unsere Session.</h3><p>YouTube-Kooperation mit Musik, Verlinkung und Drohnen-Shots eurer Location.</p><ul><li>60–180 Minuten</li><li>Afro, Organic &amp; Deep House</li><li>Details nach Absprache</li></ul><a href="#contact" class="text-link" data-booking="YouTube-Kooperation">Kooperation anfragen {ARROW}</a></article><article class="service-card reveal"><span class="service-index">03 / ALL NIGHT</span><h3>Vom ersten Track<br>bis zum letzten.</h3><p>All Night Long. Ein durchgehender musikalischer Bogen für euren ganzen Abend.</p><ul><li>Bis zu 9 Stunden</li><li>Genre nach Absprache</li><li>Equipment wird vor Ort gestellt</li></ul><a href="#contact" class="text-link" data-booking="All Night Long">Nacht planen {ARROW}</a></article></div><p class="price-note">* Preisangabe aus unserem bisherigen Angebot. Den konkreten Umfang und aktuellen Preis bestätigen wir in eurer Anfrage.</p></div></section>'''
CONTACT=f'''<section id="contact" class="section contact-section"><div class="container contact-layout"><div class="contact-copy reveal"><p class="eyebrow"><span>06 /</span> Let's make it happen</p><h2>Der nächste<br>gute Abend<br>beginnt <em>hier.</em></h2><p>Club-Slot, Rooftop, private Session oder gemeinsame Idee: Wir freuen uns, von euch zu hören.</p><a class="contact-email" href="mailto:zweiklangkontakt@gmail.com">zweiklangkontakt@gmail.com {ARROW}</a><div class="contact-direct"><a href="tel:+4915679748536">+49 156 79748536</a><a href="https://wa.me/4915679748536" target="_blank" rel="noopener noreferrer">WhatsApp {ARROW}</a></div><div class="contact-signature">ghostak <span>&amp;</span> artemis</div></div><div class="reveal">{booking_form()}</div></div></section>'''
HERO=f'''<section id="hero" class="hero"><div class="container"><div class="hero-topline"><p class="eyebrow"><span class="status-dot"></span> Independent DJ duo · Freiburg im Breisgau</p><span class="hero-coordinate">48° N / 7° E</span></div><div class="hero-layout"><div class="hero-copy"><h1>Zwei Köpfe.<br>Ein <em>Groove.</em></h1><p>House, der sich nach dem Moment anfühlt.<br>Von der goldenen Stunde bis tief in die Nacht.</p><div class="hero-actions"><a class="button" href="#music">{PLAY} Unseren Sound entdecken</a><a class="text-link" href="#contact">Booking {ARROW}</a></div><div class="hero-genres"><span>Deep House</span><span>Organic</span><span>Afro House</span></div></div><div class="hero-visual"><div class="hero-photo-wrap"><img class="hero-photo" src="{REMOTE}zweiklang.jpg" alt="ZweiKlang – ghostak und artemis" width="900" height="1000" fetchpriority="high"><div class="photo-shade"></div><div class="photo-label"><span>FROM FREIBURG<br>WITH GROOVE.</span><a href="videos.html" aria-label="Unsere Live-Sessions ansehen">{ARROW}</a></div><div class="hero-image-fallback" aria-hidden="true">Zwei<br>Klang.</div></div><div class="floating-note"><span class="note-spark" aria-hidden="true">✳</span><span>Two minds.<br>One frequency.</span></div></div></div><div class="hero-bottom"><span>ghostak &amp; artemis</span><a href="#music">Runterkommen. Reinhören. <span>↓</span></a><span>115—130 BPM</span></div></div></section><div class="genre-band" aria-hidden="true"><div>GOOD MUSIC <span>✳</span> GOOD COMPANY <span>✳</span> ZWEIKLANG <span>✳</span> HOUSE MUSIC <span>✳</span> FREIBURG <span>✳</span></div></div>'''
SESSIONS=f'''<section id="watch" class="section sessions-section"><div class="container">{section_head('02','Recorded moments','Nicht nur hören.<br><em>Dabei sein.</em>','<a class="text-link" href="videos.html">Alle '+str(len(VIDEO_IDS))+' Sessions '+ARROW+'</a>')}<div class="sessions-grid">{video_cards(VIDEO_IDS[-3:][::-1])}</div><div class="sessions-bottom"><span>Besondere Orte. Echte Sessions. Unser Sound.</span><a href="https://www.youtube.com/@zweiklang_music" target="_blank" rel="noopener noreferrer">Zum YouTube-Kanal {ARROW}</a></div></div></section>'''
page('index','ZweiKlang · Zwei Köpfe. Ein Groove.','ZweiKlang: ghostak & artemis aus Freiburg. Deep, Organic und Afro House. Live-Sessions entdecken und euren nächsten Gig anfragen.',HERO+MUSIC+SESSIONS+ABOUT+EVENTS+SERVICES+CONTACT)
# Keep the complete older prose accessible, without presenting unconfirmed template claims as current facts.
def legacy(name):
 source=(REF/(name+'.html')).read_text(); main=re.search(r'<main id="main">([\s\S]*?)</main>',source).group(1)
 main=re.sub(r'<!--.*?-->','',main,flags=re.S)
 main=re.sub(r'<[^>]+>',' ',main)
 main=html.unescape(re.sub(r'\s+',' ',main)).strip()
 return f'<div class="container legacy-wrap"><details class="legacy"><summary>Ältere Angaben aus dem bisherigen Webauftritt</summary><p class="legacy-notice">Historischer Stand: Diese Angaben enthalten abweichende Beschreibungen und sind nicht als bestätigte aktuelle Termine, Referenzen oder Leistungen zu verstehen.</p><p>{html.escape(main)}</p></details></div>'
page('about','Das Duo · ZweiKlang','Lerne ghostak & artemis kennen. Zwei Freunde aus Freiburg, eine gemeinsame Begeisterung für House.',f'<section class="page-intro container"><p class="eyebrow">Das Duo / Freiburg</p><h1>Zusammen klingt’s<br><em>einfach besser.</em></h1><p>House ist unser gemeinsamer Nenner. Alles andere entsteht im Moment.</p></section>'+ABOUT.replace('href="about.html">Mehr über ZweiKlang','href="contact.html">Mit uns planen')+f'<section class="section container"><div class="story-grid"><h2>Vom Zuhören<br>zum <em>Auflegen.</em></h2><div><p class="lead">Wir haben uns schon immer für House begeistert – und irgendwann beschlossen, selbst gemeinsam hinter die Decks zu gehen.</p><p>Ob Bar, Club oder draußen: Wir stimmen jedes Set auf den Ort und die Stimmung ab. Seit 2025 halten wir unsere Sessions auch auf YouTube fest. Artemis ergänzt die Aufnahmen mit Drohnen-Shots.</p><div class="inline-links"><a href="videos.html">Sessions ansehen {ARROW}</a><a href="contact.html">Mit uns planen {ARROW}</a></div></div></div></section>'+legacy('about'))
page('videos','Alle Sessions · ZweiKlang','Alle elf ZweiKlang DJ-Sets aus dem bisherigen Webauftritt. Entdecke unsere Live-Sessions auf YouTube.',f'<section class="page-intro container"><p class="eyebrow">Sessions / The collection</p><h1>Ein Ort.<br>Ein Set. <em>Ein Gefühl.</em></h1><p>Unsere Sessions zum Eintauchen – direkt auf YouTube.</p></section><section class="section video-collection"><div class="container"><div class="collection-toolbar"><p><strong>{len(VIDEO_IDS)}</strong> Sessions</p><label class="search-label"><span class="sr-only">Sessions durchsuchen</span><input type="search" id="session-search" placeholder="Session suchen, z. B. 07" autocomplete="off"></label></div><p id="search-status" class="sr-only" role="status" aria-live="polite"></p><div class="sessions-grid all-sessions">{video_cards(VIDEO_IDS[::-1])}</div><p class="empty-state" hidden>Keine Session gefunden. Versuche eine andere Nummer.</p></div></section>'+legacy('videos'))
page('events','Live & Eventarchiv · ZweiKlang','Rückblicke auf ZweiKlang-Sessions in Freiburg. Für neue Termine und Bookings direkt anfragen.',f'<section class="page-intro container"><p class="eyebrow">Live / In good company</p><h1>Am besten<br><em>zusammen.</em></h1><p>Musik ist ein guter Grund, sich zu treffen.</p><a class="button" href="contact.html">Einen Abend planen {ARROW}</a></section>'+EVENTS.replace('href="#contact"','href="contact.html"').replace('href="events.html">Zum Eventarchiv','href="contact.html">Booking anfragen')+f'<section class="section container"><div class="story-grid"><h2>Weitere<br><em>Erinnerungen.</em></h2><div class="past-notes"><article><span class="eyebrow">Gig-Archiv · 2025</span><h3>Fili Café</h3><p>Afterwork am 16. Dezember · All Night Long am 30. November.</p></article><article><span class="eyebrow">Gig-Archiv · 2025</span><h3>Wakepark Tunisee</h3><p>Dark Afro House DJ Set.</p></article></div></div></section>'+legacy('events'))
old=(ROOT/'previous-version/contact.html').read_text()
legal=re.search(r'<section class="section" id="legal">[\s\S]*?</section>',old).group(0)
privacy=re.search(r'<section class="section" id="privacy">[\s\S]*?</section>',old).group(0)
legal=re.sub(r'<!--.*?-->','',legal,flags=re.S).replace('Rechtliche Hinweise (§ 5 TMG)','Impressum').replace('class="section"','class="section legal-section"')
privacy=privacy.replace('class="section"','class="section legal-section"').replace('Bilder werden von GitHub (raw.githubusercontent.com) und YouTube (i.ytimg.com) geladen.','Ein Teil der Bilder wird lokal bereitgestellt. Weitere Bilder werden von GitHub (raw.githubusercontent.com) und YouTube (i.ytimg.com) geladen.')
privacy=privacy.replace('Diese Website ist für die Bereitstellung über OpenAI Sites vorbereitet.','Diese Website wird über GitHub Pages bereitgestellt.').replace('Ein Teil der Bilder wird lokal bereitgestellt. Weitere Bilder werden von GitHub (raw.githubusercontent.com) und YouTube (i.ytimg.com) geladen.','Fotos und Logos werden zusammen mit dieser Website über GitHub Pages bereitgestellt. Video-Vorschaubilder werden von YouTube (i.ytimg.com) geladen.')
page('contact','Booking & Kontakt · ZweiKlang','Plane euren nächsten Abend mit ZweiKlang. Booking, Kooperationen, Impressum und Datenschutz.',CONTACT.replace('<h2>', '<h1>', 1).replace('</h2>', '</h1>', 1)+legal+privacy)
